import { useState } from 'react';
import { createRoot } from 'react-dom/client';
import './styles.css';

const photos = [
  'https://images.unsplash.com/photo-1551107696-a4b0c5a0d9a2?auto=format&fit=crop&w=1200&q=85',
  'https://images.unsplash.com/photo-1600185365483-26d7a4cc7519?auto=format&fit=crop&w=1200&q=85',
  'https://images.unsplash.com/photo-1552346154-21d32810aba3?auto=format&fit=crop&w=1200&q=85',
  'https://images.unsplash.com/photo-1460353581641-37b add?auto=format&fit=crop&w=1200&q=85'
];
const colors = [
  { name: 'Ocean / Cloud', value: '#1e526c', detail: 'ocean' },
  { name: 'Onyx / Stone', value: '#25282a', detail: 'onyx' },
  { name: 'Fog / Moss', value: '#a2aa9b', detail: 'fog' }
];
const sizes = ['US 7', 'US 7.5', 'US 8', 'US 8.5', 'US 9', 'US 9.5', 'US 10', 'US 10.5', 'US 11', 'US 11.5', 'US 12', 'US 13'];
const faqs = [
  ['Is the Trail Runner 2 waterproof?', 'The Trail Runner 2 is built with a water-resistant upper that keeps light rain and trail spray out while staying breathable. For full waterproof protection, pair it with our Ridge shell.'],
  ['How does the fit run?', 'It fits true to size with a comfortably roomy toe box. If you are between sizes, we recommend choosing the larger size for long trail days.'],
  ['Can I return my shoes if they do not work out?', 'Absolutely. Enjoy free returns within 30 days, even if you have taken them out for a test walk.'],
  ['What terrain are these made for?', 'From packed dirt to rocky singletrack, the Trail Runner 2 is ready for varied terrain and everyday adventures.']
];

function Icon({ name, size = 18 }) {
  const paths = {
    search: <><circle cx="11" cy="11" r="6.5" /><path d="m16 16 5 5" /></>,
    user: <><circle cx="12" cy="8" r="3.5" /><path d="M5 21c.7-3.4 2.9-5 7-5s6.3 1.6 7 5" /></>,
    bag: <><path d="M5 8h14l1 13H4L5 8Z" /><path d="M9 9V6a3 3 0 0 1 6 0v3" /></>,
    heart: <path d="M20.8 8.9c0 5.2-8.8 10.1-8.8 10.1S3.2 14.1 3.2 8.9A4.6 4.6 0 0 1 12 6.5a4.6 4.6 0 0 1 8.8 2.4Z" />,
    arrow: <><path d="M5 12h14" /><path d="m13 6 6 6-6 6" /></>,
    back: <><path d="M19 12H5" /><path d="m11 18-6-6 6-6" /></>,
    plus: <><path d="M12 5v14M5 12h14" /></>,
    minus: <path d="M5 12h14" />,
    close: <><path d="M5 5l14 14M19 5 5 19" /></>,
    chevron: <path d="m6 9 6 6 6-6" />,
    info: <><circle cx="12" cy="12" r="9" /><path d="M12 11v5M12 8h.01" /></>,
    check: <path d="m5 12 4 4L19 6" />
  };
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">{paths[name]}</svg>;
}

function App() {
  const [photo, setPhoto] = useState(0);
