      </header>

      <main>
        <div className="breadcrumb"><a href="#">Shop</a><span>/</span><a href="#">Trail</a><span>/</span><span>Trail Runner 2</span></div>
        <section className="product">
          <div className="gallery">
            <div className={`photo photo-${photo} color-${color.detail}`} style={{ backgroundImage: `url(${photos[photo]})` }}>
