              <button className="gallery-arrow previous" onClick={() => setPhoto((photo + photos.length - 1) % photos.length)} aria-label="Previous image"><Icon name="back" /></button>
              <button className="gallery-arrow next" onClick={() => setPhoto((photo + 1) % photos.length)} aria-label="Next image"><Icon name="arrow" /></button>
              <div className="dots">{photos.map((_, index) => <button key={index} className={photo === index ? 'active' : ''} onClick={() => setPhoto(index)} aria-label={`View image ${index + 1}`} />)}</div>
            </div>
            <div className="gallery-caption"><span>Built for the long way around.</span><span>Scroll to explore ↓</span></div>
          </div>
          <div className="details">
            <div className="eyebrow">STRIDE / TRAIL COLLECTION</div>
            <h1>Trail Runner 2</h1>
