            {tab === 'Reviews' && <div className="reviews-panel"><div className="review-score"><strong>4.9</strong><span>★★★★★</span><small>Based on 128 reviews</small></div><div className="review-quote">“The perfect shoe for morning trail loops and city miles alike. Comfortable right out of the box.”<small>— Jamie R., verified buyer</small></div></div>}
            {tab === 'Shipping & returns' && <div className="shipping-panel"><div><span>01</span><h3>Fast, free delivery</h3><p>Free standard shipping on orders over $100. Most orders arrive in 2–4 business days.</p></div><div><span>02</span><h3>Try them for 30 days</h3><p>Walk, run, explore. If they are not right for you, returns are always free within 30 days.</p></div><div><span>03</span><h3>Need a hand?</h3><p>Our trail experts are here Monday–Friday, 9am–5pm PT.</p></div></div>}
