        <div className="breadcrumb"><a href="#">Shop</a><span>/</span><a href="#">Trail</a><span>/</span><span>Trail Runner 2</span></div>
        <section className="product">
          <div className="gallery">
            <div className={`photo photo-${photo} color-${color.detail}`} style={{ backgroundImage: `url(${photos[photo]})` }}>
              <div className="photo-label">TRAIL SERIES <span>02 / 04</span></div>
              <button className="gallery-arrow previous" onClick={() => setPhoto((photo + photos.length - 1) % photos.length)} aria-label="Previous image"><Icon name="back" /></button>
              <button className="gallery-arrow next" onClick={() => setPhoto((photo + 1) % photos.length)} aria-label="Next image"><Icon name="arrow" /></button>
              <div className="dots">{photos.map((_, index) => <button key={index} className={photo === index ? 'active' : ''} onClick={() => setPhoto(index)} aria-label={`View image ${index + 1}`} />)}</div>
            </div>
            <div className="gallery-caption"><span>Built for the long way around.</span><span>Scroll to explore ↓</span></div>
          </div>
          <div className="details">
            <div className="eyebrow">STRIDE / TRAIL COLLECTION</div>
            <h1>Trail Runner 2</h1>
            <p className="subtitle">All-terrain comfort for wherever the path leads.</p>
            <div className="rating"><span>★★★★★</span> <u>4.9</u> <a href="#reviews">(128 reviews)</a></div>
            <div className="price-row"><span className="price">$145.00</span><span className="tax">Includes taxes <span className="info"><Icon name="info" size={13} /><span className="tooltip">Taxes are included in the price shown.</span></span></span></div>
            <div className="rule" />
            <div className="choice-block"><div className="choice-heading"><span>Color</span><strong>{color.name}</strong></div><div className="swatches">{colors.map((item) => <button key={item.name} className={`swatch ${color.name === item.name ? 'selected' : ''}`} style={{ '--swatch': item.value }} onClick={() => setColor(item)} aria-label={item.name} />)}</div></div>
            <div className="choice-block size-block">
              <div className="choice-heading"><span>Size</span><button className="guide-link" onClick={() => setGuideOpen(true)}>Size guide <span>↗</span></button></div>
              <button className={`size-select ${sizeOpen ? 'open' : ''}`} onClick={() => setSizeOpen(!sizeOpen)}><span>{size || 'Select your size'}</span><Icon name="chevron" size={16} /></button>
              {sizeOpen && <div className="size-options">{sizes.map((item, index) => <button key={item} disabled={[1, 7].includes(index)} className={size === item ? 'chosen' : ''} onClick={() => { setSize(item); setSizeOpen(false); }}>{item}{[1, 7].includes(index) && <small>Sold out</small>}</button>)}</div>}
            </div>
            <div className="buy-row"><div className="quantity"><button onClick={() => changeQuantity(-1)} aria-label="Decrease quantity"><Icon name="minus" size={15} /></button><input value={quantity} onChange={(event) => setQuantity(Math.max(1, Math.min(10, Number(event.target.value) || 1)))} aria-label="Quantity" /><button onClick={() => changeQuantity(1)} aria-label="Increase quantity"><Icon name="plus" size={15} /></button></div><button className="add-button" onClick={addToCart}>Add to cart <Icon name="arrow" size={17} /></button><button className={`wishlist ${wishlisted ? 'saved' : ''}`} onClick={() => setWishlisted(!wishlisted)} aria-label="Save to wishlist"><Icon name="heart" /></button></div>
            <div className="shipping-note"><span>↗</span> Free shipping & easy returns <span className="divider">·</span> Ships in 1–2 days</div>
            {notice && <div className="notice"><Icon name={notice.includes('added') ? 'check' : 'info'} size={16} /> {notice}</div>}
          </div>
        </section>

        <section className="information" id="reviews">
          <div className="tabs">{['Details', 'Reviews', 'Shipping & returns'].map((item) => <button className={tab === item ? 'active' : ''} onClick={() => setTab(item)} key={item}>{item}{item === 'Reviews' && <sup>128</sup>}</button>)}</div>
          <div className="tab-content">
            {tab === 'Details' && <><div className="feature-intro"><div><span className="eyebrow">THE EVERYDAY TRAIL SHOE</span><h2>Go farther.<br /><em>Feel good doing it.</em></h2></div><p>Designed for the in-between places — where pavement ends and the good stuff begins. Trail Runner 2 blends a responsive ride with all-day cushioning and a grippy outsole that keeps you moving confidently over every kind of ground.</p></div><div className="feature-grid"><div><b>01</b><h3>Trail-ready grip</h3><p>Our directional lug pattern finds traction on rock, dirt, and everything between.</p></div><div><b>02</b><h3>Cloud-soft landing</h3><p>Dual-density foam gives you a cushioned step without losing your connection to the trail.</p></div><div><b>03</b><h3>Made to breathe</h3><p>Lightweight engineered mesh keeps air moving when the miles stack up.</p></div></div></>}
            {tab === 'Reviews' && <div className="reviews-panel"><div className="review-score"><strong>4.9</strong><span>★★★★★</span><small>Based on 128 reviews</small></div><div className="review-quote">“The perfect shoe for morning trail loops and city miles alike. Comfortable right out of the box.”<small>— Jamie R., verified buyer</small></div></div>}
            {tab === 'Shipping & returns' && <div className="shipping-panel"><div><span>01</span><h3>Fast, free delivery</h3><p>Free standard shipping on orders over $100. Most orders arrive in 2–4 business days.</p></div><div><span>02</span><h3>Try them for 30 days</h3><p>Walk, run, explore. If they are not right for you, returns are always free within 30 days.</p></div><div><span>03</span><h3>Need a hand?</h3><p>Our trail experts are here Monday–Friday, 9am–5pm PT.</p></div></div>}
          </div>
        </section>

        <section className="faq"><div><span className="eyebrow">GOOD TO KNOW</span><h2>Questions,<br /><em>answered.</em></h2></div><div className="faq-list">{faqs.map(([question, answer], index) => <div className={`faq-item ${openFaq === index ? 'expanded' : ''}`} key={question}><button onClick={() => setOpenFaq(openFaq === index ? null : index)}><span>{question}</span><span className="faq-icon">{openFaq === index ? '−' : '+'}</span></button>{openFaq === index && <p>{answer}</p>}</div>)}</div></section>
      </main>
      <footer><div className="footer-top"><div className="footer-brand"><a className="logo" href="#"><span className="logo-mark">✦</span> stride</a><p>Made for the long way around.</p><div className="socials"><a href="#">ig</a><a href="#">𝕏</a><a href="#">◎</a><a href="#">in</a></div></div><div><h4>Help</h4><a href="#">Contact us</a><a href="#">Shipping & returns</a><a href="#">Size guide</a><a href="#">Careers</a></div><div><h4>About Stride</h4><a href="#">Our story</a><a href="#">Materials</a><a href="#">Journal</a><a href="#">Stores</a></div><div className="newsletter"><h4>Stay on the trail</h4><p>New gear, trail notes, and 10% off your first order.</p><div className="email"><input placeholder="Your email address" /><button>→</button></div></div></div><div className="footer-bottom"><span>© 2025 Stride Running Co.</span><span>Privacy · Terms · Accessibility</span><span>Canada / CAD <span className="globe">◎</span></span></div></footer>
      {guideOpen && <div className="modal-backdrop" onClick={() => setGuideOpen(false)}><div className="size-guide" onClick={(event) => event.stopPropagation()}><button className="modal-close" onClick={() => setGuideOpen(false)}><Icon name="close" /></button><span className="eyebrow">FIND YOUR FIT</span><h2>Size guide</h2><p>Measure your foot from heel to longest toe while standing. We recommend sizing up if you are between sizes.</p><div className="unit-toggle"><button className={unit === 'US' ? 'active' : ''} onClick={() => setUnit('US')}>US</button><button className={unit === 'EU' ? 'active' : ''} onClick={() => setUnit('EU')}>EU</button></div><label>Foot length <span>cm</span><input type="number" placeholder="e.g. 26.5" value={footLength} onChange={(event) => setFootLength(event.target.value)} /></label><div className="recommended"><span>Recommended size</span><strong>{estimatedSize}</strong></div><div className="chart">{[['US', 'EU', 'CM'], ['7', '39', '25'], ['8', '41', '26'], ['9', '42', '27'], ['10', '44', '28'], ['11', '45', '29'], ['12', '46', '30']].map((row, index) => <div className={index === 0 ? 'chart-head' : ''} key={row[0]}>{row.map((cell) => <span key={cell}>{cell}</span>)}</div>)}</div></div></div>}
    </div>
  );
}

createRoot(document.getElementById('root')).render(<App />);

